sealed class WindTerrainClient {
 readonly string cache;readonly Dictionary<string,byte[]> memory=new Dictionary<string,byte[]>();readonly Dictionary<string,WindRgbTile> elevation=new Dictionary<string,WindRgbTile>();readonly Dictionary<string,WindCoverTiff> cover=new Dictionary<string,WindCoverTiff>();CancellationToken cancellation;IProgress<string> progress;
 public WindTerrainClient(string directory=null){cache=directory??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DTCE Tool Kit","WindData");Directory.CreateDirectory(cache);}
 internal byte[] Fetch(string url,long first=-1,long last=-1){cancellation.ThrowIfCancellationRequested();string key;using(var sha=SHA256.Create())key=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(url+"|"+first+"|"+last))).Replace("-","");byte[] bytes;if(memory.TryGetValue(key,out bytes))return bytes;string file=Path.Combine(cache,key+".cache");if(File.Exists(file)){bytes=File.ReadAllBytes(file);memory[key]=bytes;return bytes;}if(progress!=null)progress.Report("Loading public elevation / land-cover tiles…");ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(url);request.Timeout=request.ReadWriteTimeout=20000;request.UserAgent="DTCE-Tool-Kit-Wind/"+Engine.Version;if(first>=0)request.AddRange(first,last);using(var cancel=cancellation.Register(()=>request.Abort()))using(var response=(HttpWebResponse)request.GetResponse()){if(first>=0&&response.StatusCode!=HttpStatusCode.PartialContent)throw new Exception("WorldCover server did not honor partial read.");if(response.ContentLength>5000000)throw new Exception("Unexpected wind tile size.");using(var stream=response.GetResponseStream())using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int read;while((read=stream.Read(buffer,0,buffer.Length))>0){cancellation.ThrowIfCancellationRequested();output.Write(buffer,0,read);if(output.Length>5000000)throw new Exception("Wind tile too large.");}bytes=output.ToArray();}}if(first>=0&&bytes.LongLength!=last-first+1)throw new Exception("Incomplete WorldCover partial read.");string temp=file+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllBytes(temp,bytes);try{File.Move(temp,file);}catch(IOException){File.Delete(temp);}memory[key]=bytes;return bytes;}
 public double Elevation(double lat,double lon){double x=(lon+180)/360*4096*256,phi=lat*Math.PI/180,y=(1-Math.Log(Math.Tan(phi)+1/Math.Cos(phi))/Math.PI)/2*4096*256;int px=(int)Math.Floor(x),py=(int)Math.Floor(y);double dx=x-px,dy=y-py;Func<int,int,double> sample=(a,b)=>{string key=(a/256)+"/"+(b/256);WindRgbTile tile;if(!elevation.TryGetValue(key,out tile)){tile=WindPngTile.Decode(Fetch("https://s3.amazonaws.com/elevation-tiles-prod/terrarium/12/"+key+".png"));elevation[key]=tile;}int i=((b%256)*256+a%256)*3;return tile.Rgb[i]*256+tile.Rgb[i+1]+tile.Rgb[i+2]/256.0-32768;};return sample(px,py)*(1-dx)*(1-dy)+sample(px+1,py)*dx*(1-dy)+sample(px,py+1)*(1-dx)*dy+sample(px+1,py+1)*dx*dy;}
 public int Cover(double lat,double lon){int south=(int)Math.Floor(lat/3)*3,west=(int)Math.Floor(lon/3)*3;string key=(south<0?"S":"N")+Math.Abs(south).ToString("00",CultureInfo.InvariantCulture)+(west<0?"W":"E")+Math.Abs(west).ToString("000",CultureInfo.InvariantCulture);WindCoverTiff tile;if(!cover.TryGetValue(key,out tile)){string url="https://esa-worldcover.s3.eu-central-1.amazonaws.com/v200/2021/map/ESA_WorldCover_10m_2021_v200_"+key+"_Map.tif";tile=new WindCoverTiff(Fetch(url,0,65535),url,this);cover[key]=tile;}return tile.Sample(lat,lon);}
 public WindTerrain Load(double lat,double lon,double radius,CancellationToken token,IProgress<string> notify=null){WindTin.Validate(lat,lon);cancellation=token;progress=notify;var data=new WindTerrain{Lat=lat,Lon=lon,Radius=radius,Acquired=DateTime.UtcNow};for(int n=0;n<24;n++){double bearing=n/3*45+(n%3-1)*22.5;for(double d=0;d<=radius+.1;d+=25){token.ThrowIfCancellationRequested();var p=WindAssessment.Destination(lat,lon,bearing,d);data.Rays[n].Add(new WindSample{Lat=p[0],Lon=p[1],D=d,Z=n%3==1?Elevation(p[0],p[1]):double.NaN,Cover=Cover(p[0],p[1])});}if(notify!=null)notify.Report("Sampled sector ray "+(n+1)+" of 24.");}for(int n=0;n<8;n++){var crest=data.Rays[n*3+1].Concat(data.Rays[((n+4)%8)*3+1]).OrderByDescending(p=>p.Z).First();for(double d=-radius;d<=radius+.1;d+=100){token.ThrowIfCancellationRequested();var p=WindAssessment.Destination(crest.Lat,crest.Lon,n*45+90,d);data.Cross[n].Add(new WindSample{Lat=p[0],Lon=p[1],D=d,Z=Elevation(p[0],p[1])});}}if(notify!=null)notify.Report("Mapping surface-roughness zones around the project…");
 var grid=new WindCoverGrid{Size=96,North=WindAssessment.Destination(lat,lon,0,radius)[0],South=WindAssessment.Destination(lat,lon,180,radius)[0],West=WindAssessment.Destination(lat,lon,270,radius)[1],East=WindAssessment.Destination(lat,lon,90,radius)[1],Codes=new byte[96*96]};
 for(int row=0;row<grid.Size;row++){token.ThrowIfCancellationRequested();for(int col=0;col<grid.Size;col++){double sampleLat=grid.North-(row+.5)/grid.Size*(grid.North-grid.South),sampleLon=grid.West+(col+.5)/grid.Size*(grid.East-grid.West);grid.Codes[row*grid.Size+col]=(byte)Cover(sampleLat,sampleLon);}}
 data.CoverGrid=grid;return data;}
}
sealed class WindCoverTiff {
 readonly WindTerrainClient client;readonly string url;readonly Dictionary<int,byte[]> tags=new Dictionary<int,byte[]>(),tiles=new Dictionary<int,byte[]>();readonly int width,height,tw,th;readonly uint[] offsets,sizes;readonly double left,top,sx,sy;
 public WindCoverTiff(byte[] header,string uri,WindTerrainClient owner){client=owner;url=uri;if(header.Length<8||header[0]!=73||header[1]!=73||BitConverter.ToUInt16(header,2)!=42)throw new Exception("Unsupported WorldCover TIFF.");int first=(int)BitConverter.ToUInt32(header,4),count=BitConverter.ToUInt16(header,first);for(int i=0;i<count;i++){int start=first+2+i*12,tag=BitConverter.ToUInt16(header,start),type=BitConverter.ToUInt16(header,start+2),n=(int)BitConverter.ToUInt32(header,start+4),length=checked(n*(type==3?2:type==4?4:type==12?8:1)),offset=length<=4?start+8:(int)BitConverter.ToUInt32(header,start+8);if(offset<0||length>100000||offset+length>header.Length)throw new Exception("Unsupported TIFF metadata extent.");tags[tag]=header.Skip(offset).Take(length).ToArray();}width=Int(256);height=Int(257);tw=Int(322);th=Int(323);if(Int(258)!=8||Int(259)!=8||Int(277)!=1||Int(317)!=1||tw<=0||th<=0||tw>2048||th>2048)throw new Exception("Unsupported WorldCover compression.");offsets=UInts(tags[324]);sizes=UInts(tags[325]);sx=BitConverter.ToDouble(tags[33550],0);sy=BitConverter.ToDouble(tags[33550],8);left=BitConverter.ToDouble(tags[33922],24);top=BitConverter.ToDouble(tags[33922],32);}
