 public int Sample(double lat,double lon){int x=(int)Math.Floor((lon-left)/sx),y=(int)Math.Floor((top-lat)/sy);if(x<0||y<0||x>=width||y>=height)return 0;int index=y/th*((width+tw-1)/tw)+x/tw;byte[] bytes;if(!tiles.TryGetValue(index,out bytes)){bytes=WindInflate.Decode(client.Fetch(url,offsets[index],offsets[index]+sizes[index]-1),tw*th);tiles[index]=bytes;}return bytes[(y%th)*tw+x%tw];}
}
static class WindInflate {
 public static byte[] Decode(byte[] zlib,int expected){if(zlib.Length<6||(zlib[0]&15)!=8||((zlib[0]<<8)+zlib[1])%31!=0||(zlib[1]&32)!=0)throw new Exception("Invalid zlib wind tile.");using(var input=new MemoryStream(zlib,2,zlib.Length-6))using(var decompress=new DeflateStream(input,CompressionMode.Decompress))using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int n;while((n=decompress.Read(buffer,0,buffer.Length))>0){output.Write(buffer,0,n);if(output.Length>expected)throw new Exception("Unexpected decompressed tile size.");}byte[] result=output.ToArray();if(result.Length!=expected)throw new Exception("Incomplete wind tile.");uint a=1,b=0;foreach(byte value in result){a=(a+value)%65521;b=(b+a)%65521;}uint checksum=(uint)(zlib[zlib.Length-4]<<24|zlib[zlib.Length-3]<<16|zlib[zlib.Length-2]<<8|zlib[zlib.Length-1]);if(((b<<16)|a)!=checksum)throw new Exception("Wind tile checksum mismatch.");return result;}}
}
class WindRgbTile {public byte[] Rgb;}
static class WindPngTile {
 static int Big(byte[] b,int i){return b[i]<<24|b[i+1]<<16|b[i+2]<<8|b[i+3];}static int Paeth(int a,int b,int c){int p=a+b-c,pa=Math.Abs(p-a),pb=Math.Abs(p-b),pc=Math.Abs(p-c);return pa<=pb&&pa<=pc?a:pb<=pc?b:c;}
 public static WindRgbTile Decode(byte[] data){if(data.Length<33||data[0]!=137||Encoding.ASCII.GetString(data,1,3)!="PNG")throw new Exception("Invalid elevation PNG.");int channels=0;using(var payload=new MemoryStream()){for(int p=8;p+12<=data.Length;){int length=Big(data,p);if(length<0||p+12L+length>data.Length)throw new Exception("Invalid PNG chunk.");string type=Encoding.ASCII.GetString(data,p+4,4);if(type=="IHDR"){channels=data[p+17]==2?3:data[p+17]==6?4:0;if(Big(data,p+8)!=256||Big(data,p+12)!=256||data[p+16]!=8||data[p+20]!=0||channels==0)throw new Exception("Unsupported elevation PNG.");}else if(type=="IDAT")payload.Write(data,p+8,length);p+=length+12;}if(channels==0)throw new Exception("Missing PNG dimensions.");int stride=256*channels;byte[] filtered=WindInflate.Decode(payload.ToArray(),256*(stride+1)),raw=new byte[256*stride],rgb=new byte[256*256*3];for(int y=0;y<256;y++){int filter=filtered[y*(stride+1)];if(filter>4)throw new Exception("Unknown PNG filter.");for(int x=0;x<stride;x++){int a=x>=channels?raw[y*stride+x-channels]:0,b=y>0?raw[(y-1)*stride+x]:0,c=y>0&&x>=channels?raw[(y-1)*stride+x-channels]:0,value=filter==0?0:filter==1?a:filter==2?b:filter==3?(a+b)/2:Paeth(a,b,c);raw[y*stride+x]=(byte)(filtered[y*(stride+1)+1+x]+value);}}for(int i=0;i<256*256;i++)Array.Copy(raw,i*channels,rgb,i*3,3);return new WindRgbTile{Rgb=rgb};}}
}
